<header class="admin-page-head"><div><p class="admin-eyebrow">Team / access</p><h1>Users</h1><p class="admin-lede">People who can help operate the Raspina catalogue.</p></div><a class="admin-primary-button" href="<?= e(admin_url('/users/new')) ?>">Add user <span aria-hidden="true">-&gt;</span></a></header>
<?php if (!empty($admin_error)): ?><div class="admin-alert error" role="alert"><?= e($admin_error) ?></div><?php endif; ?>
<section class="admin-panel admin-table-panel"><div class="table-toolbar"><form class="admin-search" method="get" action="<?= e(admin_url('/users')) ?>"><label class="sr-only" for="user-search">Search users</label><input id="user-search" type="search" name="q" value="<?= e($query ?? '') ?>" placeholder="Search name, email or role"><button type="submit">Search</button></form><span class="toolbar-meta"><?= count((array) $users) ?> members</span></div><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Name</th><th>Role</th><th>Status</th><th>Last login</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody><?php foreach ((array) $users as $member): ?><tr><td class="table-primary" data-label="Name"><a href="<?= e(admin_url('/users/edit/' . (int) $member['id'])) ?>"><?= e($member['name']) ?></a><small><?= e($member['email']) ?><?= !empty($member['title']) ? ' / ' . e($member['title']) : '' ?></small></td><td data-label="Role"><?= e($member['role_title'] ?: $member['role'] ?: 'Unassigned') ?></td><td data-label="Status"><span class="status-pill <?= !empty($member['is_active']) ? 'instock' : '' ?>"><i></i><?= !empty($member['is_active']) ? 'Active' : 'Inactive' ?></span></td><td class="mono-cell" data-label="Last login"><?= !empty($member['last_login_at']) ? e($member['last_login_at']) : 'Never' ?></td><td data-label="Actions"><div class="table-actions"><a class="icon-action" href="<?= e(admin_url('/users/edit/' . (int) $member['id'])) ?>">Edit</a><?php if ((int) $member['id'] !== (int) ($admin_user['id'] ?? 0)): ?><form method="post" action="<?= e(admin_url('/users')) ?>" data-confirm="Change this user’s active status?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="admin_action" value="deactivate_user"><input type="hidden" name="id" value="<?= (int) $member['id'] ?>"><input type="hidden" name="active" value="<?= empty($member['is_active']) ? '1' : '0' ?>"><button class="icon-action danger" type="submit"><?= empty($member['is_active']) ? 'Activate' : 'Deactivate' ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$users): ?><div class="empty-state"><div><strong>No team members yet</strong><p>Invite the people who help shape and ship each collection.</p></div></div><?php endif; ?></section>
